package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.DisabledUserEmailTemplateVO;

class DisabledUserEmailTemplateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of disabled user email template of tenant config")
  void test_disabled_user_email_template_value_holder_assign_plain_value() {
    Object holder = new Object();
    DisabledUserEmailTemplateValueHolder<Object> value =
        new DisabledUserEmailTemplateValueHolder<>(holder);
    Assertions.assertSame(holder, value.disabledUserEmailTemplate("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDisabledUserEmailTemplateValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getDisabledUserEmailTemplate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.disabledUserEmailTemplateNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDisabledUserEmailTemplateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getDisabledUserEmailTemplate().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of disabled user email template of tenant config")
  void test_disabled_user_email_template_value_holder_assign_value_object() {
    Object holder = new Object();
    DisabledUserEmailTemplateValueHolder<Object> value =
        new DisabledUserEmailTemplateValueHolder<>(holder);
    DisabledUserEmailTemplateVO vo = DisabledUserEmailTemplateVO.from("one");
    Assertions.assertFalse(value.getDisabledUserEmailTemplateValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.disabledUserEmailTemplate(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getDisabledUserEmailTemplateValue().orElseThrow());
    Assertions.assertSame(holder, value.disabledUserEmailTemplate(Optional.empty()));
    Assertions.assertFalse(value.getDisabledUserEmailTemplateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.disabledUserEmailTemplate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDisabledUserEmailTemplateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of disabled user email template of tenant config against the original")
  void test_disabled_user_email_template_value_holder_read() {
    Object holder = new Object();
    DisabledUserEmailTemplateValueHolder<Object> value =
        new DisabledUserEmailTemplateValueHolder<>(holder);
    DisabledUserEmailTemplateVO vo = DisabledUserEmailTemplateVO.from("one");
    DisabledUserEmailTemplateVO other = DisabledUserEmailTemplateVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getDisabledUserEmailTemplateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDisabledUserEmailTemplate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDisabledUserEmailTemplate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.disabledUserEmailTemplate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDisabledUserEmailTemplate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDisabledUserEmailTemplate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of disabled user email template of tenant config")
  void test_disabled_user_email_template_value_holder_unset() {
    Object holder = new Object();
    DisabledUserEmailTemplateValueHolder<Object> value =
        new DisabledUserEmailTemplateValueHolder<>(holder);
    DisabledUserEmailTemplateVO vo = DisabledUserEmailTemplateVO.from("one");
    value.disabledUserEmailTemplate(vo);
    Assertions.assertSame(holder,
        value.unsetDisabledUserEmailTemplateIfMatches("disabledUserEmailTemplate_other"));
    Assertions.assertTrue(value.getDisabledUserEmailTemplateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetDisabledUserEmailTemplateIfMatches("disabledUserEmailTemplate"));
    Assertions.assertFalse(value.getDisabledUserEmailTemplateValue().isPresent(),
        "The field name must clear the value");
    value.disabledUserEmailTemplate(vo);
    Assertions.assertSame(holder, value.unsetDisabledUserEmailTemplate());
    Assertions.assertFalse(value.getDisabledUserEmailTemplateValue().isPresent(),
        "Unset must clear the value");
  }
}
